        k = int(next(iterator))
        x = int(next(iterator))
        a = int(next(iterator))
        b = int(next(iterator))
    except StopIteration:
        return

    total_lunches = k * x

    # If the minimum required students (a) is greater than the maximum possible lunches,
    # it's impossible to satisfy both the lunch constraint and the minimum student count.
    if a > total_lunches:
        print("impossible")
        return

    # We need to find a subset of groups such that:
    # 1. The sum of group sizes (students) <= total_lunches (no wasted lunches)
    # 2. The sum of group sizes is >= a
    # 3. The sum of group sizes is <= b
    # We want to maximize this sum.

    # Since group sizes are small (<= 100) and n is up to 1000, the maximum possible sum is 100,000.
    # We can use a boolean DP array where dp[s] is True if sum 's' is achievable.
    # However, to optimize space and time, we can use a set of reachable sums.

    reachable = {0}

    for size in groups:
        new_reachable = set()
        for s in reachable:
            new_sum = s + size
            # Pruning: if new_sum exceeds total_lunches, we don't need to track it
            # because any larger sum will also exceed total_lunches and violate the "no wasted lunches" rule.
            if new_sum <= total_lunches:
                new_reachable.add(new_sum)
        reachable.update(new_reachable)

    # Find the maximum sum in reachable that satisfies a <= sum <= b
    max_students = -1
    for s in reachable:
        if a <= s <= b:
            if s > max_students:
                max_students = s

    if max_students == -1:
        print("impossible")
    else:
        print(max_students)

