        k = int(next(iterator))
        x = int(next(iterator))
        a = int(next(iterator))
        b = int(next(iterator))
    except StopIteration:
        return

    total_capacity = k * x

    # Use a set to store all reachable sums of group sizes
    reachable = {0}

    for size in groups:
        new_sums = set()
        for current_sum in reachable:
            new_sum = current_sum + size
            # Optimization: if new_sum exceeds total_capacity, we can still keep it temporarily
            # but we know any valid answer must be <= total_capacity.
            # However, for DP state explosion prevention, we can cap or ignore if way too large?
            # Actually, since we need exact sums, and max sum is bounded by total_capacity for validity,
            # but intermediate sums might exceed. Let's just add all and filter later.
            # But to prevent memory explosion if groups are large and n is 1000, we should be careful.
            # Max possible sum is 1000 * 100 = 100,000. This is small enough for a set.
            new_sums.add(new_sum)
        reachable.update(new_sums)

    max_students = -1

    for s in reachable:
        if s > total_capacity:
            continue
        if s >= a and s <= b:
            if s % x == 0:
                if s > max_students:
                    max_students = s

    if max_students == -1:
        print("impossible")
    else:
